  if (w) r.push('Current body weight about ' + trimNum(w) + ' kg' + (h ? ', height ' + h + ' cm' : '') + (PROFILE.age ? ', age ' + PROFILE.age : '') + '.');
  if (PROFILE.jointFriendly) r.push('Go easy on joints: no running, jumping or other high-impact work, and nothing that needs getting down onto the floor and back up.');
