/** Computed from the two plans, not taken from Claude's own description. */
export function planDiff(a: Plan, b: Plan, kcal: number, protein: number, curKcal: number, curProtein: number, wn: string[]) {
  const out: string[] = [], fmtN = (x: number) => Number(x).toLocaleString('en-US');
  if (kcal !== curKcal) out.push('Calories: ' + fmtN(curKcal) + ' → ' + fmtN(kcal));
  if (protein !== curProtein) out.push('Protein: ' + curProtein + ' g → ' + protein + ' g');
  (['carb', 'fat', 'fiber'] as const).forEach((t) => { if (a.targets[t] !== b.targets[t]) out.push(t.charAt(0).toUpperCase() + t.slice(1) + ': ' + a.targets[t] + ' g → ' + b.targets[t] + ' g'); });
  const nm = (p: Plan, k: string) => (p.programs[k] || ({} as { name?: string })).name || k;
  const liftDays = (w: Plan['phases'][number]['weeks'][number]) => w.filter((sl) => sl.t === 'lift').length;
  a.phases.forEach((pa, i) => {
    const pb = b.phases[i], label = 'Phase ' + (i + 1);
    if (pa.steps !== pb.steps) out.push(label + ' steps: ' + fmtN(pa.steps) + ' → ' + fmtN(pb.steps));
    const la = liftDays(pa.weeks[0]), lb = liftDays(pb.weeks[0]);
    if (la !== lb) out.push(label + ': ' + la + ' → ' + lb + ' lifting days a week');
    const changed: string[] = [];
    for (let wi = 0; wi < 2; wi++) {
      const wa = pa.weeks[wi] || pa.weeks[0], wb = pb.weeks[wi] || pb.weeks[0];
      for (let di = 0; di < 7; di++) {
        const sa = wa[di] as any, sb = wb[di] as any;
        if (sa.t !== sb.t || sa.s !== sb.s) {
          const txt = wn[di] + ' ' + (sa.t === 'lift' ? nm(a, sa.s) : sa.t) + ' → ' + (sb.t === 'lift' ? nm(b, sb.s) : sb.t);
          if (changed.indexOf(txt) < 0) changed.push(txt);
        }
      }
    }
    if (changed.length) out.push(label + ' days: ' + changed.slice(0, 4).join('; ') + (changed.length > 4 ? ' and ' + (changed.length - 4) + ' more' : ''));
  });
  Object.keys(b.programs).forEach((k) => {
    const pb = b.programs[k], pa = a.programs[k];
    if (!pa) { out.push('New session: ' + pb.name + ' (' + pb.ex.length + ' exercises)'); return; }
    const na = pa.ex.map(exParts), nb = pb.ex.map(exParts);
    const namesA = na.map((e) => e.n), namesB = nb.map((e) => e.n);
    nb.forEach((e) => { if (namesA.indexOf(e.n) < 0) out.push(pb.name + ': add ' + e.n + ' (' + e.s + ')'); });
    na.forEach((e) => { if (namesB.indexOf(e.n) < 0) out.push(pb.name + ': drop ' + e.n); });
    nb.forEach((e) => { const i2 = namesA.indexOf(e.n); if (i2 >= 0 && na[i2].s !== e.s) out.push(pb.name + ': ' + e.n + ' ' + na[i2].s + ' → ' + e.s); });
    if (pa.name !== pb.name) out.push('Renamed ' + pa.name + ' → ' + pb.name);
  });
  Object.keys(a.programs).forEach((k) => { if (!b.programs[k]) out.push('Removed session: ' + a.programs[k].name); });
  return out;
}

// ── weekly review ──
export function reviewPrompt(gtype: string | undefined, bulk: boolean, floor: number, data: unknown) {
  const g = ({ lose: 'fat-loss', recomp: 'body-recomposition', muscle: 'muscle-building', health: 'health and habits' } as Record<string, string>)[gtype || 'lose'] || 'fitness';
  return "You are a blunt, demanding coach reviewing the last 7 days of one person's " + g + ' plan. They asked you to be brutally honest and to push them, so do exactly that. '
    + 'Use only the numbers below. Name every target they missed, on which days, by how much, and what it costs them toward the goal. '
    + 'Do not soften, do not pad, do not praise anything that only met the minimum, and never call a weak week "a good start". If a target was truly hit, say so in one line and raise the bar. '
    + 'Judge actions and numbers, never the person: no insults, no comments about their body, no food guilt. No emoji.\n\n'
    + 'Grade the week A to F on how much of the plan they actually did (sessions, protein, calories, steps, sleep, weigh-ins, habits). A means every target hit; C means about half; F means the plan mostly did not happen.\n\n'
    + 'Rules for the suggestion:\n'
    + '- Suggest at most ONE change for next week.\n'
    + (bulk ? '- A calorie increase is 100 to 200 kcal, only if weight has not risen for two weeks. A step change is 1,000 to 2,000 a day. Never cut protein.\n'
            : '- A calorie cut is 100 to 200 kcal and never takes the target below ' + floor + '. A step increase is 1,000 to 2,000 a day. Never cut protein.\n')
    + (bulk ? '- Only suggest a change if food was logged on at least 5 of the 7 days. Otherwise change is null and the suggestion is about consistency.\n'
            : '- Only suggest a calorie or step change if the 7-day average weight has not dropped compared with two weeks before AND food was logged on at least 5 of the 7 days. Otherwise change is null and the suggestion is about consistency (logging, sessions, sleep or protein).\n')
    + '- Never push eating below the calorie floor, skipping meals, fasting or training through pain. Pushing harder means consistency: sessions done, protein hit, steps walked, sleep kept.\n'
    + '- Do not comment on medicine or doses. If the numbers suggest they are unwell (very low food, no sleep), say to check with their doctor.\n\n'
    + 'Reply with ONLY JSON shaped:\n'
    + '{"grade":"C","headline":"one blunt sentence: the verdict on the week","truths":["hard truth citing a number and a day"],'
    + '"leak":"the single biggest thing that held progress back this week, with its cost","commitments":["specific, measurable commitment for next week"],'
    + '"wins":["only targets truly hit"],"suggestion":{"what":"...","why":"...","change":{"kcal":2050} or {"steps":10000} or null}}\n'
    + 'truths: 3 to 5 items, each under 22 words, each with a number from the data. commitments: exactly 3, each with a number and the days it applies to (e.g. "Hit 160 g protein on all 7 days"). wins: at most 2, empty if nothing was truly hit.\n\n'
    + 'Data:\n' + JSON.stringify(data);
}
