/** reviewDue(): at least 6 days into the goal, and a week since the last review. */
export const reviewDue = (START: string, MAXDAY: string, lastTo: string | null) =>
  diffDays(d(START), d(MAXDAY)) >= 6 && (!lastTo || diffDays(d(lastTo), d(MAXDAY)) >= 7);
export const minus = (k: string, n: number) => key(addDays(d(k), -n));
