export class AiError extends Error {
  constructor(public code: 'no_key' | 'bad_key' | 'rate_limited' | 'invalid_json' | 'timeout' | 'refusal' | 'image_rejected' | 'network' | 'overloaded', msg?: string) { super(msg || code); }
}
/** r19 claudeErr, plus the cases a bring-your-own key adds. */
export function aiMessage(e: unknown) {
  const c = e instanceof AiError ? e.code : null;
  return c === 'no_key' ? 'Add your Anthropic API key in Me, Settings, AI to use Claude here.'
    : c === 'bad_key' ? 'Anthropic did not accept that API key. Check it in Me, Settings, AI.'
    : c === 'rate_limited' ? 'Rate limited. Wait a minute and try again.'
    : c === 'invalid_json' ? 'Could not read the reply. Try describing it more plainly.'
    : c === 'timeout' ? 'Claude took too long to answer.'
    : c === 'refusal' ? 'Claude declined that request.'
    : c === 'image_rejected' ? 'That image could not be used. Try a smaller or clearer photo.'
    : c === 'overloaded' ? 'Claude is busy right now. Try again in a minute.'
    : 'Could not reach Claude just now.';
}
